package com.rumitx.app;
import android.app.*;import android.content.*;import android.os.*;import com.rumitx.recovery.BootCoordinator;
/** Foreground radio session, retained when navigating or locking the screen. */
public final class RadioService extends Service {
 private static volatile String state="Connecting to radio…";private static final java.util.concurrent.ExecutorService lifecycle=java.util.concurrent.Executors.newSingleThreadExecutor(r->new Thread(r,"RumiTX-radio-lifecycle"));private static volatile RadioService live;private static volatile boolean txNoted;private volatile boolean stopped;private HidlAdapter hidl;private VoiceTxBridge voiceBridge;private BroadcastReceiver txReceiver;
 public static String status(){return state;}
 public static void noteTx(boolean on){txNoted=on;RadioService self=live;if(self!=null)self.showTx(on);}
 public static void start(Context c){c.startForegroundService(new Intent(c,RadioService.class));}
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();live=this;NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("rumitx_radio","Radio receiver",NotificationManager.IMPORTANCE_LOW));nm.createNotificationChannel(new NotificationChannel("rumitx_tx","Transmit",NotificationManager.IMPORTANCE_DEFAULT));startForeground(241,notification());RadioController radio=RadioController.getInstance();MessageStore.attach(this,radio);radio.setIdentity(DmrIdentity.id(this));radio.setConnectionListener(this::update);lifecycle.execute(()->initialize(radio));voiceBridge = new VoiceTxBridge(this, radio);txReceiver = voiceBridge.receiver();registerReceiver(txReceiver,new IntentFilter(VoiceTxBridge.ACTION));AgentRuntime.start(this,radio,voiceBridge);}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}return START_STICKY;}
 private Notification notification(){PendingIntent open=PendingIntent.getActivity(this,241,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent stop=PendingIntent.getService(this,242,new Intent(this,RadioService.class).setAction("STOP"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String title=txNoted?"RumiTX · radio receiver · TRANSMITTING":"RumiTX · radio receiver";return new Notification.Builder(this,"rumitx_radio").setSmallIcon(R.drawable.ic_tak_notification).setContentTitle(title).setContentText(state).setContentIntent(open).addAction(new Notification.Action.Builder(null,"STOP RADIO",stop).build()).setOngoing(true).setOnlyAlertOnce(true).build();}
 private void showTx(boolean on){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(!on){nm.cancel(242);nm.notify(241,notification());return;}PendingIntent open=PendingIntent.getActivity(this,243,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notice=new Notification.Builder(this,"rumitx_tx").setSmallIcon(R.drawable.ic_tak_notification).setContentTitle("RumiTX · TRANSMITTING").setContentText("PTT is keyed. It releases on stop, disconnect, or the max key timer.").setContentIntent(open).setOngoing(true).setOnlyAlertOnce(true).build();nm.notify(242,notice);nm.notify(241,notification());}
 private void update(String text){if(stopped)return;state=text;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(241,notification());}
 private void initialize(RadioController radio){try{if(!radio.connect()){while(!stopped&&!radio.isConnected())Thread.sleep(250);}if(stopped)return;BootCoordinator b=new BootCoordinator(line->RadioLog.i("RumiTX-Coord",line));b.verifyHelper(new HelperAdapter(radio),false);hidl=new HidlAdapter(getApplicationContext());hidl.setRxListener(value->update(value==1?"RX audio route open":"Radio ready · receiver standing by"));BootCoordinator.Outcome o=b.enableRx(hidl,BootCoordinator.AppStartOwner.HELPER,1);update(o.failure==null?"Radio ready · receiver standing by":"RX setup failed: "+o.failure);long selected=getSharedPreferences("radio_session",0).getLong("active_channel",-1);ChannelDatabase database=new ChannelDatabase(this);try{for(Channel c:database.getAllChannels())if(c.id==selected){if(!radio.programChannel(c))update("Channel restore failed · select a channel");break;}}finally{database.close();}radio.requestInbox();}catch(Exception e){update("Radio setup failed: "+e.getMessage());RadioLog.e("RumiTX",state,e);}}
 public void onDestroy(){ stopped=true;state="Radio stopped · reopen RumiTX to listen";AgentRuntime.stop();noteTx(false);if(live==this)live=null; if(txReceiver!=null){try{unregisterReceiver(txReceiver);}catch(RuntimeException ignored){}} Runnable cleanup=()->lifecycle.execute(()->{  RadioController radio=RadioController.getInstance();  radio.setConnectionListener(null);radio.pttUp();  if(hidl!=null)hidl.closeAudio();radio.disconnect(); }); if(voiceBridge!=null)voiceBridge.shutdown(cleanup);else cleanup.run(); stopForeground(true);super.onDestroy();}
}
